import { contrastRatio, hexToRgb, relativeLuminance } from "@rumahl/ui/color";

/** Softer inks are preferred as long as they remain comfortably readable. */
const MAIN_TARGET = 5;
const MUTED_TARGET = 4.5;

const MAIN_ON_DARK = ["#9fb1b6", "#b9c8cc", "#d3dfe2", "#eef3f4", "#ffffff"];
const MAIN_ON_LIGHT = ["#5f6d73", "#48555b", "#303a40", "#1a2126", "#0b0d12"];
const MUTED_ON_DARK = ["#93a5aa", "#a6b7bb", "#b9c8cc", "#ccd8db"];
const MUTED_ON_LIGHT = ["#6f7d83", "#5a676d", "#455158", "#303a40"];

function pick(background: string, candidates: readonly string[], target: number): string {
  for (const candidate of candidates) {
    if (contrastRatio(candidate, background).ratio >= target) return candidate;
  }
  return candidates.at(-1)!;
}

function isLight(background: string): boolean {
  return relativeLuminance(hexToRgb(background)) > 0.35;
}

/** Prefer an intermediate ink, falling back to near-white/near-black only when needed. */
export function adaptiveInk(background: string): string {
  return isLight(background)
    ? pick(background, MAIN_ON_LIGHT, MAIN_TARGET)
    : pick(background, MAIN_ON_DARK, MAIN_TARGET);
}

export function adaptiveMuted(background: string): string {
  return isLight(background)
    ? pick(background, MUTED_ON_LIGHT, MUTED_TARGET)
    : pick(background, MUTED_ON_DARK, MUTED_TARGET);
}

export function adaptiveShadow(background: string): string {
  return isLight(background)
    ? "0 1px 2px rgba(255, 255, 255, 0.42)"
    : "0 1px 2px rgba(0, 0, 0, 0.42)";
}
